<?php

namespace Database\Seeders;

use App\Models\Country;
use Illuminate\Database\Seeder;
use Illuminate\Support\Arr;

/**
 * Mirrors the ISO 3166-1 catalogue below into the countries table. Adding a
 * country or fixing a demonym is: edit the array in this file, then reseed.
 *
 * THE LIST LIVES HERE, NOT IN CONFIG. It is seed content — read once, by this
 * class, to fill a table nothing else consults the array for — and config/ is for
 * settings the running app reads. A 249-row translated catalogue sitting in
 * config/ meant `config:cache` serialised a quarter of a megabyte of demonyms
 * into every request's bootstrap for the sake of one command that runs at deploy.
 *
 * Keyed on `code` and refreshed on every run, like LanguagesSeeder and unlike the
 * firstOrCreate content seeders: this is ISO metadata, not something an admin
 * authors, so a reseed SHOULD correct it. `is_enabled` is left out of the payload
 * — that one IS an admin decision; the column defaults to true on create.
 */
class CountriesSeeder extends Seeder
{
    public function run(): void
    {
        foreach ($this->countries() as $country) {
            $model = Country::firstOrNew(['code' => $country['code']]);

            // Merge: a locale the config does not carry (fr, es…) survives a reseed.
            $model->fill($model->mergeTranslations(Arr::except($country, 'code')))->save();
        }
    }

